import { useTheme } from '@emotion/react';
import useEmblaCarousel from 'embla-carousel-react';
import * as React from 'react';
import { useEffect } from 'react';
import { useTranslation } from 'react-i18next';

import CloudOffIcon from '@mui/icons-material/CloudOff';
import { Box, Button, Grow, Typography, alpha } from '@mui/material';

import { NextButton, PrevButton, usePrevNextButtons } from 'components/menu/gameCarousel/EmblaCarouselArrowButtons';
import FunTypo from 'components/ui/FunTypo';
import { useGameConfig, useLanguage, useLastGameCategory } from 'store/selector';
import { getGameSVG, pxToRem } from 'util/util';

const NewGameCategories = (props) => {
    const { handleClickGameCategory } = props;
    const theme = useTheme();
    const { t, i18n } = useTranslation();
    const lastGameCategoryKey = useLastGameCategory();
    const gameConfig = useGameConfig();
    const language = useLanguage();

    const OPTIONS = { dragFree: true, containScroll: false };
    const [emblaRef, emblaApi] = useEmblaCarousel(OPTIONS);

    useEffect(() => {
        if (!emblaApi || !gameConfig.gameCategories || !lastGameCategoryKey) return;
        const gameIndex = gameConfig.gameCategories.findIndex((m) => m.key === lastGameCategoryKey);
        emblaApi.scrollTo(gameIndex, true);
    }, [lastGameCategoryKey, emblaApi]);
    const { prevBtnDisabled, nextBtnDisabled, onPrevButtonClick, onNextButtonClick } = usePrevNextButtons(emblaApi);

    return (
        <>
            <Typography
                variant="h2"
                display="block"
                width="100%"
                fontSize={pxToRem(32)}
                fontWeight="800"
                textAlign="center"
                mb={pxToRem(20)}
            >
                <FunTypo
                    text={t('Game modes')}
                    color={theme.palette.text.main.replace('#', '')}
                    stroke={false}
                    strokeWidth={pxToRem(2)}
                    distance={pxToRem(3)}
                    sx={{
                        fontSize: pxToRem(40),
                        lineHeight: pxToRem(30),
                        fontWeight: 800,
                    }}
                />
                {t('Game modes2') && (
                    <>
                        <br />
                        <FunTypo
                            text={t('Game modes2')}
                            color={theme.palette.text.main.replace('#', '')}
                            stroke={false}
                            strokeWidth={pxToRem(2)}
                            distance={pxToRem(3)}
                            sx={{
                                fontSize: pxToRem(40),
                                lineHeight: pxToRem(30),
                                fontWeight: 800,
                            }}
                        />
                    </>
                )}
            </Typography>
            <Box
                ref={emblaRef}
                sx={{
                    maxWidth: '100%',
                    padding: '32px',
                    my: '-32px',
                    '@media (min-width: 641px)': {
                        maskImage: 'linear-gradient(90deg, transparent 0%, black 5%, black 95%, transparent 100%)',
                    },
                }}
            >
                <Box
                    sx={{
                        display: 'flex',
                        touchAction: 'pan-y pinch-zoom',
                        marginLeft: 'calc(1rem * -1)',
                    }}
                >
                    {gameConfig.gameCategories.map((gameCat, index) => {
                        // todo: sort offline last
                        const isDisabled = gameCat.disabledOffline && !navigator.onLine;
                        const shadowAlpha = isDisabled ? 0.05 : 0.15;
                        return (
                            <Box
                                key={gameCat.key}
                                sx={{
                                    transform: 'translate3d(0, 0, 0)',
                                    flex: `0 0 ${pxToRem(220)}`,
                                    minWidth: 0,
                                    pl: '1rem',
                                    overflowY: 'visible',
                                    position: 'relative',
                                }}
                            >
                                <Grow in={true} timeout={index * 100 + 200} key={gameCat.key}>
                                    <Button
                                        variant="mode"
                                        size="large"
                                        disabled={isDisabled}
                                        sx={{
                                            width: '100%',
                                            display: 'flex',
                                            flexDirection: 'column',
                                            alignItems: 'center',
                                            position: 'relative',
                                            overflow: 'hidden',
                                            px: 0,
                                            pt: pxToRem(40),
                                            pb: pxToRem(48),
                                            // '&:hover': {
                                            //     backgroundColor: theme.palette.background.tileHover,
                                            // },
                                            'svg:first-of-type': {
                                                color: isDisabled
                                                    ? theme.palette.neutral[300]
                                                    : theme.palette.secondary.contrast,
                                                height: pxToRem(96),
                                                width: pxToRem(96),
                                                fill: 'currentColor',
                                                filter: `drop-shadow(4px 4px 0px ${alpha(theme.palette.shadow, shadowAlpha)})`,
                                            },
                                        }}
                                        onClick={(e) => handleClickGameCategory(gameCat.key)}
                                    >
                                        {getGameSVG(gameCat.key)}
                                        <FunTypo
                                            text={gameCat.name[i18n.language]}
                                            color={(isDisabled
                                                ? theme.palette.neutral[300]
                                                : theme.palette.secondary.contrast
                                            ).replace('#', '')}
                                            stroke={false}
                                            strokeWidth={pxToRem(2)}
                                            distance={pxToRem(2)}
                                            sx={{
                                                fontSize: pxToRem(28),
                                                lineHeight: pxToRem(30),
                                                fontWeight: 800,
                                                mt: pxToRem(20),
                                                px: pxToRem(8),
                                            }}
                                        />
                                        {isDisabled && (
                                            <CloudOffIcon
                                                width={pxToRem(16)}
                                                height={pxToRem(16)}
                                                color={theme.palette.neutral[300]}
                                                sx={{
                                                    position: 'absolute',
                                                    bottom: pxToRem(8),
                                                }}
                                            />
                                        )}
                                        {/*language === 'fra' && (gameCat.notTranslated || gameCat.semiTranslated) && (
                                            <Typography
                                                display="flex"
                                                flexDirection="column"
                                                justifyContent="center"
                                                alignItems="center"
                                                backgroundColor={theme.palette.neutral[100]}
                                                color={theme.palette.neutral[400]}
                                                sx={{
                                                    fontSize: pxToRem(12),
                                                    position: 'absolute',
                                                    top: pxToRem(8),
                                                    left: pxToRem(-38),
                                                    height: pxToRem(36),
                                                    width: pxToRem(136),
                                                    transform: 'rotate(-40deg)',
                                                    span: {
                                                        display: 'block',
                                                        lineHeight: pxToRem(14),
                                                    },
                                                }}
                                            >
                                                <span>{t('eng')}</span>
                                                {gameCat.semiTranslated ? <span>/ {t('fra')}</span> : null}
                                            </Typography>
                                        )*/}
                                        {language === 'fra' && (gameCat.notTranslated || gameCat.semiTranslated) && (
                                            <Typography
                                                display="flex"
                                                flexDirection="column"
                                                justifyContent="center"
                                                alignItems="center"
                                                color={theme.palette.secondary.contrast}
                                                sx={{
                                                    fontSize: pxToRem(10),
													fontWeight: 800,
                                                    position: 'absolute',
                                                    bottom: 0,
                                                    left: 0,
                                                    height: pxToRem(24),
                                                    width: "100%",
													opacity: 0.5,
                                                    lineHeight: pxToRem(10),
                                                }}
                                            >
                                                <span>* {t('eng')}{gameCat.semiTranslated ? ` / ${t('fra')}` : null}</span>
                                            </Typography>
                                        )}
                                    </Button>
                                </Grow>
                            </Box>
                        );
                    })}
                </Box>
            </Box>
            <Box display="flex" flexDirection="row" justifyContent="space-between" width="100%">
                <PrevButton onClick={onPrevButtonClick} disabled={prevBtnDisabled} />
                <NextButton onClick={onNextButtonClick} disabled={nextBtnDisabled} />
            </Box>
        </>
    );
};

export default NewGameCategories;
